INSERT INTO episodes (id, season_number, episode_number, title, air_date, runtime_minutes, director, writers_json, summary, themes_json, character_ids_json, event_ids_json) VALUES ('s06e08', 6, 8, 'No One', '2016-06-12', 58, 'Mark Mylod', '["David Benioff","D. B. Weiss"]', 'Arya defeats the Waif and reclaims her name, Jaime takes Riverrun through Edmure, and Daenerys returns as Meereen comes under attack.', '["Identity","Power","War"]', '["arya-stark","jaime-lannister","brienne-of-tarth","daenerys-targaryen","sandor-clegane"]', '[]');
