INSERT INTO episodes (id, season_number, episode_number, title, air_date, runtime_minutes, director, writers_json, summary, themes_json, character_ids_json, event_ids_json) VALUES ('s08e01', 8, 1, 'Winterfell', '2019-04-14', 53, 'David Nutter', '["Dave Hill"]', 'Jon and Daenerys bring their armies to Winterfell, Sam reveals Jon''s true name, Theon rescues Yara, and Jaime faces Bran again.', '["Identity","Family","Duty"]', '["jon-snow","daenerys-targaryen","samwell-tarly","jaime-lannister","cersei-lannister"]', '[]');
INSERT INTO episodes (id, season_number, episode_number, title, air_date, runtime_minutes, director, writers_json, summary, themes_json, character_ids_json, event_ids_json) VALUES ('s08e02', 8, 2, 'A Knight of the Seven Kingdoms', '2019-04-21', 57, 'David Nutter', '["Bryan Cogman"]', 'Winterfell''s defenders settle old debts and share a final night together as Jaime knights Brienne and Jon tells Daenerys his parentage.', '["Duty","Love","Death"]', '["jaime-lannister","brienne-of-tarth","jon-snow","daenerys-targaryen","sansa-stark"]', '[]');
INSERT INTO episodes (id, season_number, episode_number, title, air_date, runtime_minutes, director, writers_json, summary, themes_json, character_ids_json, event_ids_json) VALUES ('s08e03', 8, 3, 'The Long Night', '2019-04-28', 81, 'Miguel Sapochnik', '["David Benioff","D. B. Weiss"]', 'Winterfell survives the longest night through terrible sacrifice when Arya reaches the godswood and destroys the Night King.', '["War","Death","Survival"]', '["arya-stark","the-night-king","bran-stark","theon-greyjoy","daenerys-targaryen"]', '["ev-s8-winterfell"]');
INSERT INTO episodes (id, season_number, episode_number, title, air_date, runtime_minutes, director, writers_json, summary, themes_json, character_ids_json, event_ids_json) VALUES ('s08e04', 8, 4, 'The Last of the Starks', '2019-05-05', 77, 'David Nutter', '["David Benioff","D. B. Weiss"]', 'Victory gives way to rivalry and grief as Jon''s secret spreads, Rhaegal is killed, Missandei is executed, and Daenerys turns toward vengeance.', '["Power","Betrayal","Revenge"]', '["daenerys-targaryen","jon-snow","sansa-stark","jaime-lannister","missandei"]', '[]');
INSERT INTO episodes (id, season_number, episode_number, title, air_date, runtime_minutes, director, writers_json, summary, themes_json, character_ids_json, event_ids_json) VALUES ('s08e05', 8, 5, 'The Bells', '2019-05-12', 77, 'Miguel Sapochnik', '["David Benioff","D. B. Weiss"]', 'King''s Landing surrenders, but Daenerys burns the city while Jaime and Cersei die together and Arya escapes the devastation.', '["War","Power","Death"]', '["daenerys-targaryen","jon-snow","tyrion-lannister","jaime-lannister","arya-stark"]', '["ev-s8-kingslanding","ev-s8-cersei-jaime-death"]');
INSERT INTO episodes (id, season_number, episode_number, title, air_date, runtime_minutes, director, writers_json, summary, themes_json, character_ids_json, event_ids_json) VALUES ('s08e06', 8, 6, 'The Iron Throne', '2019-05-19', 78, 'David Benioff & D. B. Weiss', '["David Benioff","D. B. Weiss"]', 'Jon kills Daenerys to end her conquest, Bran is chosen king, the North becomes independent, and the surviving Starks choose separate futures.', '["Power","Justice","Freedom"]', '["jon-snow","daenerys-targaryen","tyrion-lannister","bran-stark","sansa-stark"]', '["ev-s8-dany-death","ev-s8-bran-king"]');
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q1', 'ned-stark', 'Winter is coming.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q2', 'ned-stark', 'The man who passes the sentence should swing the sword.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q3', 'tyrion-lannister', 'I drink and I know things.', 5);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q4', 'tyrion-lannister', 'Never forget what you are. The rest of the world will not. Wear it like armor and it can never be used to hurt you.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q5', 'cersei-lannister', 'When you play the game of thrones, you win or you die. There is no middle ground.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q6', 'jon-snow', 'I know nothing, Jon Snow.', 2);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q7', 'daenerys-targaryen', 'I am not going to stop the wheel. I''m going to break the wheel.', 5);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q8', 'daenerys-targaryen', 'Dracarys.', 3);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q9', 'arya-stark', 'A girl has no name.', 6);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q10', 'arya-stark', 'What do we say to the god of death? Not today.', 7);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q11', 'arya-stark', 'Valar Morghulis. Valar Dohaeris.', 4);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q12', 'varys', 'Power resides where men believe it resides. It''s a trick, a shadow on the wall.', 2);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q13', 'petyr-baelish', 'Chaos isn''t a pit. Chaos is a ladder.', 3);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q14', 'sandor-clegane', 'Anyone who tells you fighting is easy is talking about someone else''s fight.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q15', 'olenna-tyrell', 'Tell Cersei. I want her to know it was me.', 7);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q16', 'tywin-lannister', 'A lion doesn''t concern himself with the opinion of a sheep.', 4);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q17', 'jaime-lannister', 'The things I do for love.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q18', 'hodor', 'Hodor.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q19', 'samwell-tarly', 'I''m not going to be the maester who ran away from the battle. Not anymore.', 6);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q20', 'brienne-of-tarth', 'I don''t want to marry a knight of the flowers or a knight of anything. I want to be a knight myself.', 4);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q21', 'melisandre', 'The night is dark and full of terrors.', 2);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q22', 'bronn', 'I like it when a girl fights back. Some girls fight back and just fight back and lose. I like the ones smart enough to know they can''t win.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q23', 'khal-drogo', 'This one belongs to me. Moon of my life.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q24', 'robb-stark', 'The Lannisters are not the only ones who pay their debts.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q25', 'davos-seaworth', 'The Red Woman would have you believe there are two sides to this world, light and darkness. Watch your step. It''s just a long drop to a cold, hard stone floor.', 5);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q26', 'beric-dondarrion', 'The Lord of Light has more use for a thief than a king.', 3);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q27', 'jorah-mormont', 'Whatever I am now, I was a knight once, and I learned the words when I was a boy. As a knight, I vow to protect the weak.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q28', 'joffrey-baratheon', 'Everyone is mine to torment.', 2);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q29', 'ygritte', 'You know nothing, Jon Snow.', 3);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q30', 'pycelle', 'Knowledge is a weapon, Jorah. Arm yourself well before you march into battle.', 2);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q31', 'stannis-baratheon', 'I will not question the Lord of Light''s plans.', 3);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q32', 'margaery-tyrell', 'It''s not easy being learned as well as beautiful.', 3);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q33', 'gendry-baratheon', 'I don''t want to be a lord. I want to fight for Ned Stark''s daughter.', 8);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q34', 'missandei', 'All men must die. But we are not men.', 6);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q35', 'grey-worm', 'There is only the fight.', 3);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q36', 'oberyn-martell', 'Everyone is mine to torment... said the wrong man. It''s the Mountain who''s mine.', 4);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q37', 'tormund-giantsbane', 'I''m gonna die at the wrong end of a pointy stick, cut down by some raggedy little farmer boy... in the muck, screaming for me mother.', 6);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q38', 'sansa-stark', 'I''m a slow learner, it''s true, but I learn.', 7);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q39', 'bran-stark', 'I''m not really anyone anymore.', 7);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q40', 'walder-frey', 'The Freys and the Starks are friends again.', 3);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q41', 'high-sparrow', 'There is only one war that matters, the war between the living and the dead.', 6);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q42', 'shae', 'I''m yours and you''re mine.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q43', 'loras-tyrell', 'The things we do for love.', 1);
INSERT INTO quotes (id, character_id, quote_text, season_number) VALUES ('q44', 'robert-baratheon', 'I was born to rule ten thousand years ago.', 1);
INSERT INTO battles (id, name, season_number, location, combatants_json, outcome, casualties, linked_character_ids_json, linked_event_ids_json) VALUES ('battle-blackwater', 'Battle of the Blackwater', 2, 'King''s Landing', '[{"side":"House Lannister / House Tyrell","houses":["Lannister","Tyrell"],"characters":["tyrion-lannister","cersei-lannister","sandor-clegane"]},{"side":"House Baratheon (Stannis)","houses":["Baratheon"],"characters":["stannis-baratheon","davos-seaworth","matthos-seaworth"]}]', 'Lannister/Tyrell victory. Tyrion''s wildfire ambush devastates Stannis''s fleet; Tywin and Loras Tyrell''s relief force routs the remaining attackers.', 'Most of Stannis''s fleet and army destroyed; Matthos Seaworth killed.', '["tyrion-lannister","stannis-baratheon","davos-seaworth","matthos-seaworth","cersei-lannister","sandor-clegane"]', '["ev-s2-blackwater"]');
INSERT INTO battles (id, name, season_number, location, combatants_json, outcome, casualties, linked_character_ids_json, linked_event_ids_json) VALUES ('red-wedding', 'The Red Wedding', 3, 'The Twins, Riverlands', '[{"side":"House Stark / House Tully","houses":["Stark","Tully"],"characters":["robb-stark","catelyn-stark","talisa-stark"]},{"side":"House Frey / House Bolton","houses":["Tully","Stark"],"characters":["walder-frey","roose-bolton"]}]', 'Frey/Bolton massacre. Under guest right, Walder Frey and Roose Bolton ambush and slaughter the Stark host during a wedding feast.', 'Robb Stark, Catelyn Stark, Talisa Stark, and most of the Northern army killed.', '["robb-stark","catelyn-stark","talisa-stark","walder-frey","roose-bolton","arya-stark"]', '["ev-s3-redwedding"]');
INSERT INTO battles (id, name, season_number, location, combatants_json, outcome, casualties, linked_character_ids_json, linked_event_ids_json) VALUES ('trial-mountain-viper', 'Trial by Combat: The Mountain vs. The Red Viper', 4, 'King''s Landing', '[{"side":"House Lannister (champion: Gregor Clegane)","houses":["Lannister"],"characters":["gregor-clegane","cersei-lannister"]},{"side":"House Martell (champion: Oberyn Martell) for Tyrion","houses":["Martell","Lannister"],"characters":["oberyn-martell","tyrion-lannister"]}]', 'Gregor Clegane wins after a brutal fight, crushing Oberyn''s skull; Tyrion is condemned to death (and later flees the city).', 'Oberyn Martell killed.', '["gregor-clegane","oberyn-martell","tyrion-lannister","ellaria-sand"]', '["ev-s4-mountain-viper"]');
INSERT INTO battles (id, name, season_number, location, combatants_json, outcome, casualties, linked_character_ids_json, linked_event_ids_json) VALUES ('battle-hardhome', 'Battle of Hardhome', 5, 'Hardhome, beyond the Wall', '[{"side":"Night''s Watch / Free Folk","houses":["Night''s Watch","Free Folk"],"characters":["jon-snow","tormund-giantsbane","karsi"]},{"side":"The Army of the Dead","houses":["Free Folk"],"characters":["the-night-king"]}]', 'Crushing defeat for the living. The Night King''s army overwhelms Hardhome; Jon Snow and a fraction of the wildlings barely escape by boat.', 'Thousands of wildlings killed and raised as wights; Karsi killed.', '["jon-snow","tormund-giantsbane","karsi","the-night-king"]', '["ev-s5-hardhome"]');
INSERT INTO battles (id, name, season_number, location, combatants_json, outcome, casualties, linked_character_ids_json, linked_event_ids_json) VALUES ('battle-bastards', 'Battle of the Bastards', 6, 'Winterfell', '[{"side":"House Stark / Free Folk / Knights of the Vale","houses":["Stark","Free Folk","Arryn"],"characters":["jon-snow","sansa-stark","tormund-giantsbane","yohn-royce"]},{"side":"House Bolton","houses":["Stark"],"characters":["ramsay-bolton","smalljon-umber"]}]', 'Stark victory. Jon''s forces are nearly annihilated until Sansa''s secret alliance with the Knights of the Vale arrives to crush the Bolton flank; Ramsay is fed to his own hounds.', 'Smalljon Umber and Wun Wun killed; House Bolton wiped out.', '["jon-snow","sansa-stark","ramsay-bolton","wun-wun","smalljon-umber","tormund-giantsbane"]', '["ev-s6-bastards"]');
INSERT INTO battles (id, name, season_number, location, combatants_json, outcome, casualties, linked_character_ids_json, linked_event_ids_json) VALUES ('sept-of-baelor', 'Destruction of the Great Sept of Baelor', 6, 'King''s Landing', '[{"side":"House Lannister (Cersei)","houses":["Lannister"],"characters":["cersei-lannister","qyburn"]},{"side":"The Faith Militant / House Tyrell","houses":["Tyrell"],"characters":["high-sparrow","margaery-tyrell","loras-tyrell","mace-tyrell"]}]', 'Cersei detonates wildfire beneath the Sept during Loras and Cersei''s trials, annihilating the Faith Militant leadership and House Tyrell''s ruling line in one stroke.', 'High Sparrow, Margaery Tyrell, Loras Tyrell, Mace Tyrell, Kevan Lannister, Lancel Lannister all killed.', '["cersei-lannister","margaery-tyrell","loras-tyrell","mace-tyrell","high-sparrow","tommen-baratheon"]', '["ev-s6-sept-explosion"]');
INSERT INTO battles (id, name, season_number, location, combatants_json, outcome, casualties, linked_character_ids_json, linked_event_ids_json) VALUES ('loot-train', 'The Loot Train Battle', 7, 'The Roseroad, Reach', '[{"side":"House Targaryen (Dothraki)","houses":["Targaryen"],"characters":["daenerys-targaryen"]},{"side":"House Lannister","houses":["Lannister"],"characters":["jaime-lannister","bronn","randyll-tarly"]}]', 'Targaryen victory. Drogon and the Dothraki bloodriders annihilate the Lannister supply train; Jaime nearly dies charging Daenerys before Bronn pulls him from the river.', 'Heavy Lannister losses; Randyll Tarly''s forces routed.', '["daenerys-targaryen","jaime-lannister","bronn"]', '["ev-s7-loot-castamere"]');
INSERT INTO battles (id, name, season_number, location, combatants_json, outcome, casualties, linked_character_ids_json, linked_event_ids_json) VALUES ('battle-winterfell', 'Battle of Winterfell (The Long Night)', 8, 'Winterfell', '[{"side":"The Living: House Stark, House Targaryen, Free Folk, Night''s Watch","houses":["Stark","Targaryen","Free Folk","Night''s Watch"],"characters":["jon-snow","daenerys-targaryen","arya-stark","theon-greyjoy","jorah-mormont","lyanna-mormont"]},{"side":"The Army of the Dead","houses":["Free Folk"],"characters":["the-night-king"]}]', 'Victory for the living. After catastrophic losses, Arya Stark assassinates the Night King with a Valyrian steel dagger, instantly destroying the entire army of the dead.', 'Jorah Mormont, Theon Greyjoy, Lyanna Mormont, Edd Tollett, Beric Dondarrion, Melisandre (later) among the dead.', '["arya-stark","the-night-king","jon-snow","theon-greyjoy","jorah-mormont","lyanna-mormont","daenerys-targaryen"]', '["ev-s8-winterfell"]');
INSERT INTO battles (id, name, season_number, location, combatants_json, outcome, casualties, linked_character_ids_json, linked_event_ids_json) VALUES ('battle-kings-landing', 'Battle of King''s Landing', 8, 'King''s Landing', '[{"side":"House Targaryen","houses":["Targaryen"],"characters":["daenerys-targaryen","grey-worm","missandei"]},{"side":"House Lannister / Iron Fleet (Euron)","houses":["Lannister","Greyjoy"],"characters":["cersei-lannister","jaime-lannister","euron-greyjoy"]}]', 'Targaryen military victory, but a moral catastrophe. Euron''s scorpions cripple Daenerys''s fleet first, but after the city surrenders she burns King''s Landing to the ground regardless.', 'Missandei executed beforehand; tens of thousands of civilians killed; Cersei and Jaime Lannister die together beneath the Red Keep; Euron Greyjoy killed by Jaime.', '["daenerys-targaryen","cersei-lannister","jaime-lannister","euron-greyjoy","missandei","jon-snow"]', '["ev-s8-kingslanding","ev-s8-cersei-jaime-death"]');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s1-hand', 1, 'Ned Stark becomes Hand of the King', 'Season 1', 'politics', '["Stark","Baratheon"]', '["ned-stark","robert-baratheon"]', 'Eddard Stark reluctantly agrees to become Robert Baratheon''s Hand after Jon Arryn''s death.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s1-drogo-wed', 1, 'Daenerys weds Khal Drogo', 'Season 1', 'wedding', '["Targaryen"]', '["daenerys-targaryen","khal-drogo","viserys-targaryen"]', 'Illyrio Mopatis brokers Daenerys''s marriage to the Dothraki khal in exchange for an army to reclaim the Iron Throne.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s1-bran-fall', 1, 'Bran Stark is pushed from a tower', 'Season 1', 'other', '["Stark","Lannister"]', '["bran-stark","jaime-lannister"]', 'Jaime Lannister pushes Bran from a Winterfell tower after he witnesses Jaime and Cersei together.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s1-robert-death', 1, 'Death of Robert Baratheon', 'Season 1', 'death', '["Baratheon"]', '["robert-baratheon","cersei-lannister"]', 'Robert dies from wounds after a boar hunt engineered by Cersei''s wine.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s1-ned-death', 1, 'Execution of Ned Stark', 'Season 1', 'death', '["Stark","Lannister"]', '["ned-stark","joffrey-baratheon"]', 'Joffrey has Ned Stark publicly beheaded on the steps of the Great Sept, igniting the War of the Five Kings.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s1-drogo-death', 1, 'Death of Khal Drogo & birth of the dragons', 'Season 1', 'death', '["Targaryen"]', '["khal-drogo","daenerys-targaryen","mirri-maz-duur"]', 'Drogo dies after Mirri Maz Duur''s blood magic; Daenerys walks into his funeral pyre and emerges with three living dragons.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s2-blackwater', 2, 'Battle of the Blackwater', 'Season 2', 'battle', '["Lannister","Baratheon","Tyrell"]', '["tyrion-lannister","stannis-baratheon","cersei-lannister","davos-seaworth"]', 'Tyrion''s wildfire trap and a timely Tyrell relief force smash Stannis Baratheon''s assault on King''s Landing.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s2-renly-death', 2, 'Death of Renly Baratheon', 'Season 2', 'death', '["Baratheon"]', '["renly-baratheon","melisandre","stannis-baratheon"]', 'A shadow creature born of Melisandre and Stannis assassinates Renly on the eve of battle.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s2-robb-talisa', 2, 'Robb Stark marries Talisa', 'Season 2', 'wedding', '["Stark"]', '["robb-stark","talisa-stark"]', 'Robb breaks his betrothal to a Frey daughter to marry Talisa, sowing the seeds of the Red Wedding.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s3-redwedding', 3, 'The Red Wedding', 'Season 3', 'death', '["Stark","Tully"]', '["robb-stark","catelyn-stark","talisa-stark","walder-frey","roose-bolton"]', 'House Frey and House Bolton butcher Robb Stark, Catelyn Stark, and their bannermen at Edmure and Roslin''s wedding feast.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s3-jon-ygritte', 3, 'Jon Snow and Ygritte', 'Season 3', 'other', '["Stark","Free Folk"]', '["jon-snow","ygritte"]', 'Jon infiltrates the wildlings and falls for the spearwife Ygritte before returning to the Night''s Watch.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s3-unsullied', 3, 'Daenerys frees the Unsullied', 'Season 3', 'politics', '["Targaryen"]', '["daenerys-targaryen","grey-worm","missandei"]', 'Daenerys tricks Kraznys mo Nakloz, burns Astapor''s masters, and frees an army of Unsullied soldiers.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s4-purplewedding', 4, 'The Purple Wedding', 'Season 4', 'death', '["Lannister","Tyrell"]', '["joffrey-baratheon","olenna-tyrell","margaery-tyrell"]', 'King Joffrey is poisoned at his own wedding feast; Olenna Tyrell is later revealed as the culprit.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s4-mountain-viper', 4, 'Trial by combat: The Mountain vs. The Red Viper', 'Season 4', 'battle', '["Lannister","Martell"]', '["gregor-clegane","oberyn-martell","tyrion-lannister"]', 'Oberyn Martell fights to prove Tyrion''s innocence but is killed by Gregor Clegane in gruesome fashion.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s4-tywin-death', 4, 'Tyrion kills Tywin Lannister', 'Season 4', 'death', '["Lannister"]', '["tyrion-lannister","tywin-lannister","shae"]', 'After discovering Shae in his father''s bed, Tyrion kills her, then shoots Tywin with a crossbow and flees the city.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s4-wall-attack', 4, 'Wildling assault on Castle Black', 'Season 4', 'battle', '["Night''s Watch","Free Folk"]', '["jon-snow","mance-rayder","ygritte","grenn","pyp"]', 'Mance Rayder''s wildling host storms the Wall; Jon Snow rallies the Night''s Watch to hold Castle Black.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s5-sept-of-baelor', 5, 'Cersei''s Walk of Atonement', 'Season 5', 'other', '["Lannister"]', '["cersei-lannister","septa-unella"]', 'The Faith Militant forces Cersei to walk naked through King''s Landing as public penance.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s5-hardhome', 5, 'Battle of Hardhome', 'Season 5', 'battle', '["Night''s Watch","Free Folk"]', '["jon-snow","the-night-king","tormund-giantsbane","karsi"]', 'The Night King''s army of the dead overruns the wildling refuge at Hardhome as Jon Snow watches in horror.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s5-shireen', 5, 'Sacrifice of Shireen Baratheon', 'Season 5', 'death', '["Baratheon"]', '["shireen-baratheon","stannis-baratheon","melisandre","selyse-baratheon"]', 'Stannis allows Melisandre to burn his daughter Shireen alive to secure a victory, dooming his campaign.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s5-jon-mutiny', 5, 'Mutiny at Castle Black', 'Season 5', 'death', '["Night''s Watch"]', '["jon-snow","alliser-thorne","olly"]', 'Alliser Thorne and other Night''s Watch officers stab Jon Snow to death for bringing wildlings beyond the Wall.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s6-jon-resurrection', 6, 'Jon Snow is resurrected', 'Season 6', 'other', '["Stark","Night''s Watch"]', '["jon-snow","melisandre","davos-seaworth"]', 'Melisandre uses the Lord of Light''s magic to bring Jon Snow back from death.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s6-tower-of-joy', 6, 'Tower of Joy flashback confirms R+L=J', 'Season 6', 'other', '["Stark","Targaryen"]', '["ned-stark","lyanna-stark","rhaegar-targaryen","jon-snow"]', 'Bran witnesses the truth: Jon Snow is the son of Lyanna Stark and Rhaegar Targaryen, not Ned''s bastard.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s6-bastards', 6, 'Battle of the Bastards', 'Season 6', 'battle', '["Stark","Bolton"]', '["jon-snow","ramsay-bolton","sansa-stark","wun-wun"]', 'Jon Snow''s forces, saved by Sansa''s secret alliance with the Knights of the Vale, retake Winterfell and destroy House Bolton.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s6-sept-explosion', 6, 'Destruction of the Great Sept of Baelor', 'Season 6', 'death', '["Lannister","Tyrell"]', '["cersei-lannister","margaery-tyrell","loras-tyrell","mace-tyrell","high-sparrow"]', 'Cersei detonates wildfire beneath the Great Sept, killing the High Sparrow, the Tyrells, and the Faith Militant leadership; she is crowned queen soon after.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s6-kitn', 6, 'Jon Snow proclaimed King in the North', 'Season 6', 'coronation', '["Stark"]', '["jon-snow","sansa-stark","lyanna-mormont"]', 'Northern lords, led by Lyanna Mormont, declare Jon Snow King in the North after retaking Winterfell.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s7-loot-castamere', 7, 'Daenerys attacks the Lannister supply train', 'Season 7', 'battle', '["Targaryen","Lannister"]', '["daenerys-targaryen","jaime-lannister","bronn"]', 'Drogon and the Dothraki devastate a Lannister grain convoy at the Loot Train Battle.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s7-dragonpit', 7, 'The Dragonpit summit', 'Season 7', 'politics', '["Stark","Lannister","Targaryen"]', '["jon-snow","cersei-lannister","daenerys-targaryen","tyrion-lannister"]', 'Westeros''s rulers meet in King''s Landing''s ruined Dragonpit and agree to a truce against the army of the dead.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s7-wall-falls', 7, 'The Wall falls', 'Season 7', 'battle', '["Targaryen","Night''s Watch"]', '["the-night-king","viserion"]', 'The Night King, riding a reanimated dragon, breaches the Wall at Eastwatch, opening the North to the army of the dead.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s7-jon-dany', 7, 'Jon and Daenerys become lovers', 'Season 7', 'other', '["Stark","Targaryen"]', '["jon-snow","daenerys-targaryen"]', 'Aboard ship to Winterfell, Jon and Daenerys begin a relationship, unaware they are aunt and nephew.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s8-winterfell', 8, 'Battle of Winterfell', 'Season 8', 'battle', '["Stark","Targaryen","Free Folk","Night''s Watch"]', '["arya-stark","the-night-king","jon-snow","theon-greyjoy","lyanna-mormont","jorah-mormont","melisandre"]', 'The living make their stand against the army of the dead; Arya Stark kills the Night King, ending the Long Night.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s8-kingslanding', 8, 'Battle of King''s Landing', 'Season 8', 'battle', '["Targaryen","Lannister"]', '["daenerys-targaryen","cersei-lannister","jaime-lannister","euron-greyjoy","missandei"]', 'Daenerys''s fleet is devastated by Euron''s scorpions and Missandei is executed; Daenerys later burns King''s Landing to the ground despite the city''s surrender.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s8-cersei-jaime-death', 8, 'Deaths of Cersei and Jaime Lannister', 'Season 8', 'death', '["Lannister"]', '["cersei-lannister","jaime-lannister"]', 'The twins are crushed together beneath the collapsing Red Keep as King''s Landing burns.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s8-dany-death', 8, 'Jon Snow kills Daenerys Targaryen', 'Season 8', 'death', '["Targaryen","Stark"]', '["jon-snow","daenerys-targaryen","drogon"]', 'Jon stabs Daenerys to stop her tyranny after the burning of King''s Landing; Drogon melts the Iron Throne in grief.');
INSERT INTO story_events (id, season_number, title, event_date, event_type, houses_json, character_ids_json, summary) VALUES ('ev-s8-bran-king', 8, 'Bran Stark elected King', 'Season 8', 'coronation', '["Stark"]', '["bran-stark","tyrion-lannister","sansa-stark"]', 'A council of lords, at Tyrion''s urging, elects Bran the Broken as King of the Six Kingdoms; Sansa wins independence for the North.');
